import { ActionDefinition } from '../../../Action'
import { StringColumn, DocumentIdColumn } from '../../../../db'

export const lookupAttachment = ActionDefinition({
    $id: '6ecdee36935023005e69925cf67ffb47',
    name: 'Look Up Attachment',
    description:
        '<p>Looks up an attachment and returns the Sys ID of the attachment. If more than one attachment is present, it searches by the file name and returns the Sys ID and if there are duplicate file names then it returns the first Sys ID encountered. A JSON Object is also returned that has all the attachments returned with File name and File size properties. Server-side validation rules are enforced (data policy, business rules, dictionary-defined mandatory fields), but UI policy does not apply</p>',
    category: 'a20738df9363130079b5925cf67ffb74',
    inputs: {
        file_name: StringColumn({
            label: 'File Name',
            maxLength: 8000,
        }),
        source_record: DocumentIdColumn({
            label: 'Source Record',
            dependent: '',
            mandatory: true,
        }),
    },
    outputs: {
        parameter1: StringColumn({
            label: 'Attachment List',
            maxLength: 4000,
        }),
        parameter: StringColumn({
            label: 'Attachment Sys ID',
            maxLength: 8000,
        }),
    },
})
